(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.PCP_PLANNERS=factory()})(typeof window==='object'?window:globalThis,()=>{
  'use strict';
  const normalize=value=>String(value||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g,'');
  function parsePartsList(text,catalog){
    if(typeof text!=='string'||text.length>20000)throw Error('Paste a parts list shorter than 20,000 characters.');
    const lines=text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
    if(lines.length>50)throw Error('Use at most 50 lines.');
    return lines.map(line=>{
      const typed=line.match(/^\s*(cpu|gpu|processor|motherboard|memory|ram|ssd|hdd|psu|case|fan)\s*[:\-]\s*/i),requested=typed?({processor:'cpu',motherboard:'board',memory:'ram'})[typed[1].toLowerCase()]||typed[1].toLowerCase():null;
      const text=line.replace(/^\s*(?:cpu|gpu|processor|motherboard|memory|ram|ssd|hdd|psu|case|fan)\s*[:\-]\s*/i,'').trim(),q=normalize(text);
      if(!q||/^https?:\/\//i.test(line))return {line,status:'unresolved',candidates:[],reason:'Paste model names; URLs are never fetched.'};
      const pool=requested?catalog.filter(p=>p.cat===requested):catalog,byId=pool.filter(p=>p.id.toLowerCase()===text.toLowerCase());
      const exact=byId.length?byId:pool.filter(p=>[p.name,p.brand+' '+p.name,...(p.aliases||[])].some(x=>normalize(x)===q));
      const candidates=exact.length?exact:pool.filter(p=>normalize(p.brand+' '+p.name).includes(q)&&q.length>=5).slice(0,8);
      return {line,status:candidates.length===1?'needs_confirmation':candidates.length?'ambiguous':'unresolved',candidates:candidates.map(p=>({id:p.id,name:p.name,brand:p.brand,category:p.cat})),reason:candidates.length===1?'Confirm the exact variant before applying it.':candidates.length?'Choose the exact manufacturer variant.':'No reliable match. Select the part manually.'};
    });
  }
  function number(value,label){if(value===''||value===null||value===undefined)return null;const n=Number(value);if(!Number.isFinite(n)||n<=0||n>2000)throw Error(label+' must be greater than zero and no more than 2,000 mm.');return n;}
  function fit(inputs){
    const pairs=[['GPU length','gpuLength','gpuAllowance'],['GPU thickness / slot allowance','gpuThickness','thicknessAllowance'],['Air cooler height','coolerHeight','coolerAllowance'],['PSU body length','psuLength','psuAllowance']];
    return pairs.map(([title,a,b])=>{const part=number(inputs[a],title),space=number(inputs[b],title+' allowance');return {title,state:part===null||space===null?'needs-verification':part>space?'failed':'passed',basis:'manual measurements',reason:part===null||space===null?'Enter both measurements.':part>space?`${part} mm exceeds the entered ${space} mm allowance.`:`${part} mm is within the entered ${space} mm allowance.`,remaining:'Connector/cable bends, radiator overlap, mounting offsets and tolerances remain unverified.'}});
  }
  function display({refresh,fps}){const hz=Number(refresh);if(!Number.isFinite(hz)||hz<1||hz>1000)throw Error('Refresh rate must be from 1 to 1,000 Hz.');const rate=fps===''||fps===undefined?null:Number(fps);if(rate!==null&&(!Number.isFinite(rate)||rate<=0||rate>2000))throw Error('Observed FPS must be greater than zero and no more than 2,000.');return {refreshInterval:1000/hz,frameInterval:rate===null?null:1000/rate,source:'user-entered observation',limitation:'Intervals are calculated; neither is a measurement of input latency or a guarantee of rendered FPS.'};}
  const diagnostics={
    'low-fps':{title:'Low FPS',steps:['Record the exact game, scene, resolution, settings and driver before changing anything. Compare the same scene with the same settings.','Check the game is using the intended GPU and that the display cable is connected to its output. Use the vendor control panel and system graphics settings.','Observe whether a frame limiter, V-sync, display setting, power mode or background task explains the cap. Change one setting and repeat the same scene.','Compare a lower resolution with the same scene. A change is a diagnostic observation, not proof of a universal CPU/GPU bottleneck.'],next:'/performance/evidence/'},
    stutter:{title:'Stuttering',steps:['Record when the spikes occur: new area, first play after a patch, online match or every few seconds. Preserve your baseline.','Observe memory commitment, free disk space and background activity during the same event. An average FPS cannot establish frame-time consistency.','Allow documented shader preparation to finish. Check the publisher’s known issues before deleting caches or changing drivers.','Change one supported setting or driver version at a time, then repeat the scene. Save the previous setting for rollback.'],next:'/tools/frame-time-budget/'},
    'no-display':{title:'First boot: no display',steps:['Turn the PC off and disconnect power before checking internal cables. Follow the exact board and PSU manuals. Never open the PSU.','Check monitor input and the display connection. A CPU without integrated graphics needs a working discrete GPU output.','Consult the exact motherboard diagnostic LEDs/beeps and memory-slot instructions. Confirm CPU support and required BIOS from its support list.','Follow the board’s documented first-boot memory training procedure. Use only its official recovery/flash instructions if support is missing.'],next:'/compatibility/'},
    memory:{title:'Memory capacity or speed',steps:['Distinguish missing capacity from a lower transfer rate. Record module part numbers, count, operating rate and reported capacity.','With power disconnected, follow the board manual for seating and preferred slots. Do not assume every four-slot configuration reaches a kit’s profile rate.','Load supported defaults and test before enabling a rated XMP/EXPO profile. Profiles are overclocking settings, not an unconditional guarantee.','Check exact CPU/board support, BIOS notes and kit configuration. Absence from a QVL is not by itself proof of incompatibility.'],next:'/tools/ram-latency-calculator/'},
    storage:{title:'Storage capacity',steps:['Record used space, installed games and free-space needs. Advertised TB uses decimal units; displayed GiB uses binary units.','Use the operating system’s storage view to locate files. Back up important data before deletion, formatting or migration.','Check interface, slot length and documented lane sharing before ordering another drive. M.2 is a shape, not a guaranteed NVMe interface.','Use the existing capacity planner and verify the exact drive model and migration plan. Extra advertised sequential speed does not resolve a full disk.'],next:'/tools/storage-capacity-planner/'},
    driver:{title:'Performance after a driver update',steps:['Record the previous and new driver, game version, settings and test scene. Check whether the patch reset settings or started shader compilation.','Read the exact vendor release notes and game known issues. Download drivers only from the hardware maker.','If needed, follow the operating system or vendor’s documented rollback/reinstallation path. Keep the previous official installer and a recovery plan.','Retest the same scene after one change. Do not use registry packs, unofficial driver updaters or disabled security controls as a generic fix.'],next:'/upgrade/'}
  };
  return {normalize,parsePartsList,fit,display,diagnostics};
});
